import { expect } from '@playwright/test';

/**
 * Per-tab config
 *  type          'form' (label + control) | 'grid' (column headers + rows)
 *  fields        every label / column header, as the UI shows it (case and spaces are ignored)
 *  asterisk      fields that show a red * in the UI
 *  prefilled     fields WITHOUT an asterisk that are prefilled in the reference record
 *                (mandatory by team rule)
 *  uploads       file-upload fields (Upload / Open buttons, not text inputs)
 *  autoGenerated system-generated values (never cleared)
 *  values        data entered by fillTab() (field label -> value)
 *  dropdowns     fields that are dropdowns (an option is picked from the list)
 *  files         upload fields filled by fillTab() (field label -> file path, relative to the project root)
 *  addRow        grid tabs: click "+" when the grid has no row yet
 *  requiredFields is derived: asterisk + prefilled
 */
