export const TABS = Object.fromEntries(
    Object.entries(RAW_TABS).map(([key, tab]) => {
        const full = {
            type: 'form',
            asterisk: [],
            prefilled: [],
            uploads: [],
            autoGenerated: [],
            dropdowns: [],
            addRow: false,
            files: {},
            values: {},
            ...tab,
        };
        full.requiredFields = [...full.asterisk, ...full.prefilled];
        return [key, full];
    })
);

// Grid DOM assumptions. If the grid is not a <table> / ARIA grid, adjust these.
export const GRID = {
    header: 'th, [role="columnheader"]',
    row: 'tbody tr, [role="row"]:not(:has([role="columnheader"]))',
    cell: 'td, [role="gridcell"]',
};

export const INPUT_SELECTOR =
    'input:not([type="hidden"]):not([type="file"]), textarea, select, [role="combobox"], [role="textbox"], [contenteditable="true"]';

export class OrganizationPage {
    constructor(page) {
        this.page = page;
        this.currentKey = null;

        this.organizationMaster = page
            .getByText('Organization Master', { exact: true })
            .first();

        this.validateButton = page
            .getByRole('button', { name: /^Validate$/i })
            .first();

        this.activateButton = page
            .getByRole('button', { name: /^Activate$/i })
            .first();
    }

    // ---------- helpers ----------

    config(key) {
        const config = TABS[key];
        if (!config) {
            throw new Error(
                `Unknown organization tab "${key}". ` +
                `Available tabs: ${Object.keys(TABS).join(', ')}`
            );
        }
        return config;
    }

    escapeRegExp(value) {
        return value.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
    }

    normalise(text) {
        return text.replace(/\*/g, '').replace(/\s+/g, '').toLowerCase();
    }

    /** Matches the label ignoring case, spacing and a trailing * */
    labelPattern(field) {
        const chars = [...field.replace(/\s+/g, '')]
            .map(c => this.escapeRegExp(c))
            .join('\\s*');
        return new RegExp(`^\\s*${chars}\\s*\\*?\\s*$`, 'i');
    }

    tab(name) {
        const pattern =
            name === TABS.info.name
                ? /Organization (Master )?Info/i
                : new RegExp(this.escapeRegExp(name), 'i');

        // .first() goes AFTER .or(), otherwise the union can resolve to two elements
        // and trigger a strict-mode violation.
        return this.page
            .getByRole('tab', { name: pattern })
            .or(this.page.getByText(pattern))
            .first();
    }

    activePanel() {
        return this.page.locator('[role="tabpanel"]:visible').last();
    }

    label(field) {
        return this.activePanel().getByText(this.labelPattern(field)).first();
    }

    // ---------- navigation ----------

    async openOrganization() {
        const infoTab = this.tab(TABS.info.name);

        if (!(await infoTab.isVisible().catch(() => false))) {
            if (await this.organizationMaster.isVisible().catch(() => false)) {
                await this.organizationMaster.click();
            }
        }

        await expect(infoTab).toBeVisible({ timeout: 90_000 });
    }

    async openTab(key) {
        const config = this.config(key);
        const tab = this.tab(config.name);

        await expect(tab).toBeVisible({ timeout: 15_000 });
        await tab.scrollIntoViewIfNeeded().catch(() => { });

        // tabs hidden behind the ">" arrow: click the arrow until the tab can be clicked
        const clicked = await tab.click({ timeout: 3000 }).then(() => true).catch(() => false);
        if (!clicked) {
            await this.revealTab(tab);
            await tab.click();
        }

        this.currentKey = key;
        await this.page.waitForTimeout(500);
    }

    /** Clicks the tab bar's ">" arrow until the given tab is clickable (max 8 clicks). */
    async revealTab(tab) {
        const arrow = this.page
            .locator(
                '[aria-label*="next" i], [aria-label*="right" i], [class*="tab-next"], ' +
                '[class*="tabs-next"], [class*="nav-next"], [class*="scroll-right"], [class*="chevron-right"]'
            )
            .first();

        for (let i = 0; i < 8; i++) {
            const ok = await tab
                .click({ trial: true, timeout: 1000 })
                .then(() => true)
                .catch(() => false);
            if (ok) return;

            if (!(await arrow.isVisible().catch(() => false))) {
                throw new Error(
                    'Tab is hidden and the ">" arrow was not found. ' +
                    'Inspect the arrow in DevTools and update the locator in revealTab().'
                );
            }
            await arrow.click();
            await this.page.waitForTimeout(300);
        }
    }

    // ---------- locating controls ----------

    async gridCell(field, row = 0) {
        const panel = this.activePanel();
        const wanted = this.normalise(field);

        const headers = await panel.locator(GRID.header).allInnerTexts();
        const col = headers.findIndex(h => this.normalise(h) === wanted);

        if (col < 0) {
            throw new Error(
                `Column "${field}" not found. Headers seen: ${headers.join(' | ')}`
            );
        }

        return panel.locator(GRID.row).nth(row).locator(GRID.cell).nth(col);
    }

    async gridControl(field, row = 0) {
        const cell = await this.gridCell(field, row);
        const input = cell.locator(INPUT_SELECTOR).first();
        return (await input.count()) ? input : cell;
    }

    async fieldControl(field) {
        const panel = this.activePanel();
        const pattern = this.labelPattern(field);

        // 1. accessible label (anchored, so "CIN" never matches "CIN Upload")
        const labelled = panel.getByLabel(pattern).first();

        if ((await labelled.count()) && (await labelled.isVisible().catch(() => false))) {
            const tag = await labelled.evaluate(el => el.tagName.toLowerCase());
            const role = await labelled.getAttribute('role');

            if (['input', 'textarea', 'select'].includes(tag) ||
                ['combobox', 'textbox'].includes(role)) {
                return labelled;
            }

            const child = labelled.locator(INPUT_SELECTOR).first();
            if (await child.count()) return child;
        }

        // 2. visible label -> nearest wrapper that contains a control
        const label = this.label(field);
        await expect(label).toBeVisible({ timeout: 5000 });

        const forId = await label.getAttribute('for').catch(() => null);
        if (forId) {
            const linked = this.page.locator(`[id="${forId}"]`);
            if (await linked.count()) return linked.first();
        }

        const control = label
            .locator(
                'xpath=ancestor::*[.//input[not(@type="hidden")] or .//textarea or .//select or .//*[@role="combobox"]][1]'
            )
            .locator(INPUT_SELECTOR)
            .first();

        if (await control.count()) return control;

        throw new Error(
            `Cannot find the actual input for "${field}". ` +
            'Inspect the field in DevTools and add a specific locator.'
        );
    }

    /** Picks form or grid lookup based on the tab that was last opened / validated. */
    async control(field) {
        const config = this.config(this.currentKey);
        return config.type === 'grid'
            ? this.gridControl(field)
            : this.fieldControl(field);
    }

    // ---------- reading / writing values ----------

    async readValue(control) {
        const info = await control.evaluate(el => {
            // custom dropdowns often show the chosen text in a sibling element
            const wrapper = el.parentElement?.parentElement || el.parentElement;
            const shown = wrapper
                ?.querySelector('[class*="selected"], [class*="single-value"], [class*="value-container"]')
                ?.textContent;

            return {
                tag: el.tagName.toLowerCase(),
                value: el.value,
                text: el.textContent,
                title: el.getAttribute('title'),
                shown,
                selected: el.selectedOptions?.[0]?.textContent ?? null,
            };
        });

        if (info.tag === 'input' || info.tag === 'textarea') {
            return (info.value || info.shown || info.title || '').trim();
        }
        if (info.tag === 'select') {
            return (info.selected ?? '').trim();
        }
        return (info.text || info.shown || info.title || '').trim();
    }

    /** True when an upload field already has a file (the green "Open" button is shown). */
    async hasUploadedFile(field) {
        const config = this.config(this.currentKey);

        if (config.type === 'grid') {
            const cell = await this.gridCell(field);
            return (await cell.getByText(/^Open$/).count()) > 0;
        }

        const wrapper = this.label(field).locator(
            'xpath=ancestor::*[.//*[normalize-space()="Upload"]][1]'
        );
        return (await wrapper.getByText(/^Open$/).count()) > 0;
    }

    async clearValue(control) {
        const tag = await control.evaluate(el => el.tagName.toLowerCase());
        const role = await control.getAttribute('role').catch(() => null);
        const type = await control.getAttribute('type').catch(() => null);
        const editable = await control.isEditable().catch(() => false);

        if (!editable) {
            throw new Error('The field is disabled or read-only and cannot be cleared.');
        }

        if (tag === 'input' && ['checkbox', 'radio', 'file', 'button', 'submit'].includes(type)) {
            throw new Error(`Cannot clear field control of type "${type}" using fill().`);
        }

        if (tag === 'input' || tag === 'textarea') {
            await control.fill('');
            return;
        }

        if (tag === 'select') {
            await control.selectOption({ label: '' });
            return;
        }

        if (role === 'textbox' || (await control.getAttribute('contenteditable')) === 'true') {
            await control.fill('');
            return;
        }

        if (role === 'combobox') {
            await control.click();
            await control.press('Control+A').catch(() => { });
            await control.press('Backspace').catch(() => { });
            return;
        }

        throw new Error(`Unsupported control for clearing. Tag: ${tag}, role: ${role}.`);
    }

    async restoreValue(control, originalValue) {
        const tag = await control.evaluate(el => el.tagName.toLowerCase());
        const role = await control.getAttribute('role').catch(() => null);

        if (tag === 'input' || tag === 'textarea') {
            await control.fill(originalValue);
        } else if (tag === 'select') {
            await control
                .selectOption({ label: originalValue })
                .catch(() => control.selectOption({ value: originalValue }));
        } else if (role === 'combobox') {
            await control.click();
            await control.press('Control+A').catch(() => { });
            await control.pressSequentially(originalValue).catch(() => { });

            const option = this.page
                .getByRole('option', { name: originalValue, exact: true })
                .first();

            if (await option.isVisible().catch(() => false)) {
                await option.click();
            }
        }
    }

    /** Opens a dropdown and clicks the option that matches `value` exactly. */
    async selectFromDropdown(control, value) {
        await control.click();

        // searchable dropdowns: typing filters the list (ignored when the input is read-only)
        await control.fill(value).catch(() => { });

        const exact = new RegExp(`^\\s*${this.escapeRegExp(value)}\\s*$`, 'i');

        const option = this.page
            .getByRole('option', { name: exact })
            .or(this.page.locator('li, [role="option"], [class*="option"]').filter({ hasText: exact }))
            .first();

        await expect(
            option,
            `Dropdown option "${value}" not found. Inspect the open list in DevTools.`
        ).toBeVisible({ timeout: 5000 });

        await option.click();
    }

    async fillField(field, value) {
        const control = await this.control(field);
        const tag = await control.evaluate(el => el.tagName.toLowerCase());
        const role = await control.getAttribute('role').catch(() => null);

        if (this.config(this.currentKey).dropdowns.includes(field)) {
            await this.selectFromDropdown(control, value);
            return;
        }

        if (tag === 'input' || tag === 'textarea') {
            await control.fill(value);
            return;
        }

        if (tag === 'select') {
            await control.selectOption({ label: value });
            return;
        }

        if (role === 'combobox') {
            await control.click();

            const option = this.page
                .getByRole('option', { name: value, exact: true })
                .first();

            await expect(option).toBeVisible({ timeout: 5000 });
            await option.click();
            return;
        }

        // grid cell that only shows text until it is clicked: open the editor, then type
        if (this.config(this.currentKey).type === 'grid') {
            await control.dblclick();

            const editor = control.locator(INPUT_SELECTOR).first();
            await expect(
                editor,
                `Grid cell "${field}" did not turn into an input after a double click. ` +
                'Inspect the cell in DevTools.'
            ).toBeVisible({ timeout: 3000 });

            await editor.fill(value);
            await editor.press('Tab').catch(() => { });
            return;
        }

        throw new Error(
            `Cannot populate "${field}" automatically. ` +
            'Add field-specific logic for this control.'
        );
    }

    /**
     * Enters every value listed in the tab's `values` map.
     * Scrolls each field to the middle of the screen first (the last fields sit under the
     * floating Approvals bar), falls back to typing key by key for masked inputs, and checks
     * that text inputs really hold the value afterwards.
     */
    async fillTab(key) {
        const config = this.config(key);
        this.currentKey = key;

        if (config.addRow) await this.ensureGridRow();

        for (const [field, value] of Object.entries(config.values)) {
            const control = await this.control(field);

            await control
                .evaluate(el => el.scrollIntoView({ block: 'center', inline: 'nearest' }))
                .catch(() => { });
            await control.scrollIntoViewIfNeeded().catch(() => { });

            // plain grid cells are not inputs, so isEditable() does not apply to them
            const controlTag = await control
                .evaluate(el => el.tagName.toLowerCase())
                .catch(() => '');
            const isFormControl =
                ['input', 'textarea', 'select'].includes(controlTag) ||
                (await control.getAttribute('role').catch(() => null)) === 'combobox';

            if (isFormControl && !(await control.isEditable().catch(() => false))) {
                throw new Error(
                    `[${config.name}] "${field}" is read-only, so it cannot be filled. ` +
                    'Use the Create screen or a Draft record, not an Active one.'
                );
            }

            await this.fillField(field, value).catch(async error => {
                const tag = await control
                    .evaluate(el => el.tagName.toLowerCase())
                    .catch(() => '');
                if (tag !== 'input' && tag !== 'textarea') throw error;

                await control.click();
                await control.press('Control+A');
                await control.press('Backspace');
                await control.pressSequentially(value, { delay: 30 });
            });

            const tag = await control
                .evaluate(el => el.tagName.toLowerCase())
                .catch(() => '');

            if (tag === 'input' || tag === 'textarea') {
                const actual = await this.readValue(control);
                if (!this.sameValue(actual, value)) {
                    throw new Error(
                        `[${config.name}] "${field}" expected "${value}" but the page shows "${actual}". ` +
                        'The input may have a mask or max length.'
                    );
                }
            }
        }

        for (const [field, file] of Object.entries(config.files)) {
            await this.uploadFile(field, file);
        }

        await this.verifyValues(key);
    }

    /**
     * Exact match, except for dates: the date inputs reformat what is typed
     * (01-10-2026 becomes 01/10/2026), so dates are compared ignoring - / . separators.
     */
    sameValue(actual, expected) {
        if (actual === expected) return true;

        const isDate = v => /^\d{1,4}[-/.]\d{1,2}[-/.]\d{1,4}$/.test(v.trim());
        const digits = v => v.replace(/[-/.\s]/g, '');

        return isDate(actual) && isDate(expected) && digits(actual) === digits(expected);
    }

    /** Uploads a file into an Upload field (form or grid). The file must exist on disk. */
    async uploadFile(field, filePath) {
        const config = this.config(this.currentKey);
        const absolute = path.resolve(filePath);

        if (!fs.existsSync(absolute)) {
            throw new Error(
                `[${config.name}] upload file for "${field}" not found: ${absolute}. ` +
                'Create that file (any small PDF) or change the path in the tab config.'
            );
        }

        const scope =
            config.type === 'grid'
                ? await this.gridCell(field)
                : this.label(field).locator('xpath=ancestor::*[.//input[@type="file"]][1]');

        const fileInput = scope.locator('input[type="file"]').first();

        if (await fileInput.count()) {
            await fileInput.setInputFiles(absolute);
        } else {
            // no file input in the DOM until Upload is clicked: use the file chooser
            const chooserPromise = this.page.waitForEvent('filechooser', { timeout: 5000 });
            await scope.getByText(/^\s*Upload\s*$/).first().click();
            const chooser = await chooserPromise;
            await chooser.setFiles(absolute);
        }

        await this.page.waitForTimeout(500);
    }

    /** Grid tabs: clicks the "+" under the grid when there is no data row yet. */
    async ensureGridRow() {
        const panel = this.activePanel();

        if ((await panel.locator(GRID.row).count()) > 0) return;

        const addButton = panel
            .locator(
                'button:has-text("+"), [aria-label*="add" i], [title*="add" i], ' +
                '[class*="add-row"], [class*="addRow"], [class*="plus"]'
            )
            .first();

        await expect(
            addButton,
            'Could not find the "+" (add row) button. Inspect it in DevTools and add its locator.'
        ).toBeVisible({ timeout: 5000 });

        await addButton.click();
        await expect(panel.locator(GRID.row).first()).toBeVisible({ timeout: 5000 });
    }

    /**
     * Re-reads every value of the tab AFTER all fields are filled. Catches dropdowns /
     * autocompletes that clear typed text when focus moves to the next field.
     */
    async verifyValues(key) {
        const config = this.config(key);
        this.currentKey = key;

        for (const [field, expected] of Object.entries(config.values)) {
            const control = await this.control(field);
            const actual = await this.readValue(control);

            expect
                .soft(
                    this.sameValue(actual, expected) ||
                    actual.toLowerCase().includes(expected.toLowerCase()),
                    `[${config.name}] "${field}" should show "${expected}" but shows "${actual}"`
                )
                .toBeTruthy();
        }
    }

    async clickValidate() {
        await expect(this.validateButton).toBeVisible({ timeout: 10_000 });
        await expect(this.validateButton).toBeEnabled();
        await this.validateButton.click();
    }

    // ---------- validations ----------

    /** Every label / column header in the config is on screen (all misses reported together). */
    async validateTab(key) {
        const config = this.config(key);
        this.currentKey = key;

        await expect(this.tab(config.name)).toBeVisible({ timeout: 15_000 });
        await expect(this.activePanel()).toBeVisible({ timeout: 15_000 });

        for (const field of config.fields) {
            const label = this.label(field);
            await label.scrollIntoViewIfNeeded({ timeout: 2000 }).catch(() => { });

            await expect
                .soft(label, `[${config.name}] label/column not found: "${field}"`)
                .toBeVisible({ timeout: 3000 });
        }
    }

    /** A field shows * in the UI exactly when it is listed in `asterisk`. */
    async validateAsterisks(key) {
        const config = this.config(key);
        this.currentKey = key;

        for (const field of config.fields) {
            const text = await this.label(field)
                .textContent({ timeout: 3000 })
                .catch(() => null);

            if (text === null) continue; // reported by validateTab

            expect
                .soft(
                    text.includes('*'),
                    `[${config.name}] "${field}" asterisk mismatch (UI text: "${text.trim()}")`
                )
                .toBe(config.asterisk.includes(field));
        }
    }

    /** Every mandatory field (asterisk + prefilled) has a value / uploaded file. */
    async validatePrefilled(key) {
        const config = this.config(key);
        this.currentKey = key;

        for (const field of config.requiredFields) {
            if (config.uploads.includes(field)) {
                expect
                    .soft(
                        await this.hasUploadedFile(field),
                        `[${config.name}] "${field}" has no uploaded file`
                    )
                    .toBeTruthy();
                continue;
            }

            const control = await this.control(field);
            const value = await this.readValue(control);

            expect
                .soft(value, `[${config.name}] mandatory field "${field}" is empty`)
                .not.toBe('');
        }
    }

    /**
     * Clears one mandatory field, clicks Validate and expects an error.
     * Returns 'skipped' when the field is read-only (e.g. record is Active).
     */
    async expectRequiredFieldValidation(field, options = {}) {
        const {
            errorRegex = /required|mandatory|cannot be empty|please enter|please select|must be provided|invalid/i,
            restore = true,
        } = options;

        const control = await this.control(field);

        await control
            .evaluate(el => el.scrollIntoView({ block: 'center', inline: 'nearest' }))
            .catch(() => { });

        if (!(await control.isEditable().catch(() => false))) {
            console.warn(`"${field}" is read-only on this record - skipped.`);
            return 'skipped';
        }

        const originalValue = await this.readValue(control);

        if (!originalValue) {
            throw new Error(
                `"${field}" is already empty. ` +
                'This test expects a populated value to clear and restore.'
            );
        }

        const stateOf = async () => ({
            aria: await control.getAttribute('aria-invalid').catch(() => null),
            cls: (await control.getAttribute('class').catch(() => '')) || '',
        });

        try {
            const before = await stateOf();
            await this.clearValue(control);

            const messages = this.page.getByText(errorRegex);
            const messagesBefore = await messages.count();

            // toasts, popups and inline error elements, whatever their wording
            const alerts = this.page.locator(
                '[role="alert"], [role="dialog"], [class*="toast" i], [class*="snack" i], ' +
                '[class*="notification" i], [class*="error" i], [class*="invalid" i]'
            );
            const alertsBefore = await alerts.count();
            const textBefore = await this.page.locator('body').innerText().catch(() => '');

            await this.clickValidate();

            const gotMessage = await expect
                .poll(
                    async () =>
                        (await messages.count()) > messagesBefore ||
                        (await alerts.count()) > alertsBefore,
                    { timeout: 5000 }
                )
                .toBe(true)
                .then(() => true)
                .catch(() => false);

            // text that appeared on the page after Validate (shown in the failure message)
            const textAfter = await this.page.locator('body').innerText().catch(() => '');
            const seen = new Set(textBefore.split('\n').map(l => l.trim()));
            const newText = textAfter
                .split('\n')
                .map(l => l.trim())
                .filter(l => l && !seen.has(l))
                .slice(0, 10);

            const after = await stateOf();
            const errClass = /invalid|error/i;
            const becameInvalid =
                after.aria === 'true' ||
                (errClass.test(after.cls) && !errClass.test(before.cls));

            expect(
                gotMessage || becameInvalid,
                `Expected validation for empty mandatory field "${field}", ` +
                'but no new error message or invalid state appeared after Validate. ' +
                `New text on the page after Validate: ${newText.length ? JSON.stringify(newText) : '(none)'}`
            ).toBeTruthy();

            return 'validated';
        } finally {
            if (restore) {
                const restoreOp = this.config(this.currentKey).dropdowns.includes(field)
                    ? this.selectFromDropdown(control, originalValue)
                    : this.restoreValue(control, originalValue);

                await restoreOp.catch(error => {
                    console.warn(
                        `Could not restore "${field}". Restore it manually. ${error.message}`
                    );
                });
            }
        }
    }

    async validateRequiredFields(key) {
        const config = this.config(key);
        this.currentKey = key;

        const skipped = [];

        for (const field of config.requiredFields) {
            // uploads and system-generated values cannot be cleared with fill()
            if (config.uploads.includes(field) || config.autoGenerated.includes(field)) {
                continue;
            }

            const result = await this.expectRequiredFieldValidation(field);
            if (result === 'skipped') skipped.push(field);
        }

        expect(
            skipped,
            `[${config.name}] these mandatory fields are read-only, so the clear-and-validate ` +
            'check could not run. Use a Draft / editable record.'
        ).toEqual([]);
    }
}